function renombrarProyecto(id){
  const pr = state.proyectos.find(p => p.id === id); if(!pr) return;
  const inN = el('input', {value:pr.nombre});
  openModal('Renombrar proyecto',
    el('div', {class:'field'}, el('span', {class:'flab'}, 'Nombre'), inN),
    () => { const n = inN.value.trim(); if(!n) return false; const viejo = pr.nombre; pr.nombre = n;
      registrarCambio('proyecto', 'renombrado de "' + viejo + '" a "' + n + '"'); save(); render(); });
}
function borrarProyecto(id){
  const pr = state.proyectos.find(p => p.id === id); if(!pr) return;
  const n = state.elementos.filter(e => e.proyectoId === id).length;
  if(!confirm('Se borrará el proyecto "' + pr.nombre + '"' + (n ? ' y sus ' + n + ' elemento(s)' : '') + '. ¿Continuar?')) return;
  state.proyectos = state.proyectos.filter(p => p.id !== id);
  state.elementos = state.elementos.filter(e => e.proyectoId !== id);
  if(state.proyectoActivo === id) state.proyectoActivo = null;
  asegurarProyectoModo();
  save(); render();
}

