function dzTabla(titulo, key, cols){
  const arr = disenoDe()[key];
  const card = el('div', {class:'card', style:'margin-bottom:16px'});
  card.appendChild(el('div', {class:'card-h'},
    el('span', {class:'t'}, titulo + ' · ' + arr.length),
    el('button', {class:'btn sm', onclick:() => { arr.push({}); save(); render(); }}, '+ Fila')));
  const wrap = el('div', {class:'tablewrap', style:'margin:0;border:0;border-radius:0'});
  const tb = el('table', {class:'dztbl'});
  tb.appendChild(el('tr', null, ...cols.map(col => el('th', null, col.t)), el('th', {style:'width:38px'}, '')));
  arr.forEach((row, idx) => {
    const tr = el('tr', null);
    cols.forEach(col => {
      let inp;
      if(col.o) inp = el('select', null, el('option', {value:''}, '—'),
        ...col.o.map(o => el('option', {value:o, ...(String(row[col.k] || '') === o ? {selected:'selected'} : {})}, o)));
      else inp = el('input', {value:row[col.k] || '', placeholder:col.ph || ''});
      inp.addEventListener(col.o ? 'change' : 'input', e => { row[col.k] = e.target.value; save(); });
      tr.appendChild(el('td', null, inp));
    });
    tr.appendChild(el('td', null, el('button', {class:'btn sm ghost', title:'Quitar fila',
      onclick:() => { arr.splice(idx, 1); save(); render(); }}, '✕')));
    tb.appendChild(tr);
  });
  wrap.appendChild(tb); card.appendChild(wrap);
  return card;
}
function dzParametros(){
  const p = disenoDe().parametros;
  const mk = (lab, key, opts, rerender) => el('label', {style:'display:block'},
    el('span', {class:'flab'}, lab),
    el('select', {onchange:e => { p[key] = e.target.value; save(); if(rerender) render(); }},
      ...opts.map(o => el('option', {value:o, ...(p[key] === o ? {selected:'selected'} : {})}, o))));
  const card = el('div', {class:'card', style:'margin-bottom:16px'});
  card.appendChild(el('div', {class:'card-h'}, el('span', {class:'t'}, 'Parámetros de proyecto')));
  const b = el('div', {class:'card-b', style:'display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px'});
  b.appendChild(mk('Tipo de línea', 'linea', ['Convencional', 'Convencional (Altas Prestaciones)', 'Alta Velocidad', 'Ancho Métrico'], true));
  if(nagEsRAM(p.linea)) b.appendChild(mk('Categoría RAM', 'catAM', ['0', 'I', 'II']));
  b.appendChild(mk('Bloqueo', 'bloqueo', ['BA', 'BLA', 'BCA', 'BSL']));
  b.appendChild(mk('Sistemas', 'sistemas', ['ASFA', 'ASFA + ERTMS N1', 'ASFA + ERTMS N2', 'ERTMS N2']));
  const g = el('label', null, el('span', {class:'flab'}, 'Gradiente medio (‰) — negativo = pendiente'),
    el('input', {value:p.gradiente || '', placeholder:'-12'}));
  g.querySelector('input').addEventListener('input', e => { p.gradiente = e.target.value; save(); });
  b.appendChild(g);
  card.appendChild(b);
  /* tabla de distancia de frenado (override manual; el generador usa la NAG 0-8-5.0 automáticamente) */
  const grad = parseFloat(String(p.gradiente || '').replace(',', '.')) || 0;
  const dfWrap = el('div', {class:'card-b', style:'border-top:1px solid var(--line)'});
  dfWrap.appendChild(el('div', {style:'display:flex;align-items:center;gap:8px;margin-bottom:8px;flex-wrap:wrap'},
    el('span', {class:'flab', style:'margin:0'}, 'Distancia de frenado por velocidad (override manual)'),
    el('span', {style:'flex:1'}),
    el('button', {class:'btn sm', onclick:() => {
      const c = nagCurvaFrenado(p.linea, p.catAM, grad);
      if(!c.length){ alert('No hay tabla NAG 0-8-5.0 para esa red.'); return; }
      p.distFrenado = c; save(); render();
    }}, 'Cargar de NAG 0-8-5.0'),
    el('button', {class:'btn sm ghost', onclick:() => { p.distFrenado = clone(DZ_FRENADO_DEF); save(); render(); }}, 'Restaurar orientativa'),
    el('button', {class:'btn sm', onclick:() => { (p.distFrenado = p.distFrenado || []).push({vel:'', dist:''}); save(); render(); }}, '+ Fila')));
  const dft = el('table', {class:'dztbl', style:'max-width:340px'});
  dft.appendChild(el('tr', null, el('th', null, 'Vel (km/h)'), el('th', null, 'Distancia de frenado (m)'), el('th', {style:'width:34px'}, '')));
  (p.distFrenado || []).forEach((r, i) => {
    const iv = el('input', {value:r.vel || '', placeholder:'160'});
    const id = el('input', {value:r.dist || '', placeholder:'2700'});
    iv.addEventListener('input', e => { r.vel = e.target.value; save(); });
    id.addEventListener('input', e => { r.dist = e.target.value; save(); });
    dft.appendChild(el('tr', null, el('td', null, iv), el('td', null, id),
      el('td', null, el('button', {class:'btn sm ghost', onclick:() => { p.distFrenado.splice(i, 1); save(); render(); }}, '✕'))));
  });
  dfWrap.appendChild(el('div', {class:'tablewrap', style:'margin:0;border:0'}, dft));
  dfWrap.appendChild(el('div', {style:'color:var(--tx2);font-size:12px;margin-top:8px'},
    'El generador usa automáticamente la tabla de distancia de frenado a parada de la NAG 0-8-5.0 (ED1+M1+M2) según tipo de línea, categoría y gradiente. Esta tabla es solo un override manual para casos ad-hoc: si la rellenas, el generador la usa en vez de la NAG. «Cargar de NAG 0-8-5.0» la rellena con los valores oficiales para la red y el gradiente actuales.'));
  card.appendChild(dfWrap);
  return card;
}
async function dzDescargarPlantilla(){
  if(typeof ExcelJS === 'undefined'){ alert('No se pudo cargar la librería de Excel (sin conexión).'); return; }
  const d = disenoDe();
  const wb = new ExcelJS.Workbook(); wb.creator = 'Vía · Diseño';
  const estNombres = (d.estaciones || []).map(e => String(e.nombre || '').trim()).filter(Boolean);
  const hoja = (nombre, cols, filas) => {
    const ws = wb.addWorksheet(nombre);
    ws.columns = cols.map(col => ({header:col.t, key:col.k, width:Math.max(14, col.t.length + 4)}));
    ws.getRow(1).font = {bold:true};
    (filas || []).forEach(r => ws.addRow(r));
    for(let i = (filas ? filas.length : 0); i < 30; i++) ws.addRow({});
    cols.forEach((col, ci) => {
      const opts = col.o || (col.k === 'est' && estNombres.length ? estNombres : null);
      if(!opts) return;
      for(let r = 2; r <= 32; r++) ws.getCell(r, ci + 1).dataValidation = {type:'list', allowBlank:true, formulae:['"' + opts.join(',').replace(/"/g, '') + '"']};
    });
  };
  hoja('Vias', DZCOLS.vias, d.vias);
  hoja('Agujas', DZCOLS.agujas, d.agujas);
  hoja('Piquetes', DZCOLS.piquetes, d.piquetes);
  hoja('Estaciones', DZCOLS.estaciones, d.estaciones);
  const wp = wb.addWorksheet('Parametros');
  wp.columns = [{header:'Tipo de línea', key:'linea', width:26}, {header:'Categoría RAM', key:'catAM', width:14}, {header:'Bloqueo', key:'bloqueo', width:12}, {header:'Sistemas', key:'sistemas', width:22}, {header:'Gradiente medio (‰)', key:'gradiente', width:22}];
  wp.getRow(1).font = {bold:true};
  wp.addRow({linea:d.parametros.linea || 'Convencional', catAM:d.parametros.catAM || '', bloqueo:d.parametros.bloqueo || 'BA', sistemas:d.parametros.sistemas || 'ASFA + ERTMS N2', gradiente:d.parametros.gradiente || ''});
  [['Convencional,Convencional (Altas Prestaciones),Alta Velocidad,Ancho Métrico', 1], ['0,I,II', 2], ['BA,BLA,BCA,BSL', 3], ['ASFA,ASFA + ERTMS N1,ASFA + ERTMS N2,ERTMS N2', 4]].forEach(([lst, col]) => {
    wp.getCell(2, col).dataValidation = {type:'list', allowBlank:true, formulae:['"' + lst + '"']};
  });
  const wf = wb.addWorksheet('DistFrenado');
  wf.columns = [{header:'Vel (km/h)', key:'vel', width:14}, {header:'Distancia de frenado (m)', key:'dist', width:24}];
  wf.getRow(1).font = {bold:true};
  const gradP = parseFloat(String(d.parametros.gradiente || '').replace(',', '.')) || 0;
  const df = (d.parametros.distFrenado && d.parametros.distFrenado.length) ? d.parametros.distFrenado
    : (nagCurvaFrenado(d.parametros.linea, d.parametros.catAM, gradP).length ? nagCurvaFrenado(d.parametros.linea, d.parametros.catAM, gradP) : DZ_FRENADO_DEF);
  df.forEach(r => wf.addRow(r));
  const wg = wb.addWorksheet('Guía');
  ['PLANTILLA DE DATOS DE ENTRADA — DISEÑO NAS 811', '',
   'IMPORTANTE: la columna «Estación» de Vias, Agujas y Piquetes identifica a qué estación pertenece cada elemento. Rellénala siempre: dos vías con el mismo número en estaciones distintas (p. ej. vía 3 en PADRÓN y vía 3 en CATOIRA) son vías diferentes; sin la estación se solapan. Los nombres deben coincidir con la hoja Estaciones.',
   'Vias: una fila por vía. tipo = general / apartado / topera / banalizada. PK como 19+050 ó 19,050. Las vías GENERALES y BANALIZADAS son de línea: deja su «Estación» EN BLANCO (recorren toda la línea, no pertenecen a una estación). Solo apartaderos y toperas llevan estación.',
   'Agujas: estación + PK de la punta (JCA) + PK del piquete de vía libre. «Vía origen»/«Vía destino» son números de vía DENTRO de esa estación. «Se entra por» decide si la señal delante va a 20/30 m (punta) o a ≥5 m del piquete (talón). «Forma escape con» = nº de la aguja pareja.',
   'Piquetes: PK y las dos vías que separa.',
   'Estaciones: PK inicio y fin (repite el mismo valor para un punto).',
   'Parametros: una sola fila. Tipo de línea: Convencional / Convencional (Altas Prestaciones) / Alta Velocidad / Ancho Métrico. Categoría RAM: 0, I o II (solo si la línea es Ancho Métrico). Gradiente medio en ‰, negativo = pendiente.',
   'DistFrenado: la app ya usa automáticamente la tabla de la NAG 0-8-5.0 (ED1+M1+M2) según tipo de línea, categoría y gradiente. Esta hoja es solo un override manual: si la dejas con estos valores (los de la NAG para tus parámetros) o vacía, se usa la NAG; si pones otros, se usan esos.'
  ].forEach(t => wg.addRow([t]));
  const buf = await wb.xlsx.writeBuffer();
  descargar('plantilla_diseno_' + ((proyActivo().nombre || 'proyecto').replace(/[^\w\-]+/g, '_')) + '.xlsx', buf, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
}
function dzImportar(){
  const inp = el('input', {type:'file', accept:'.xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
  inp.addEventListener('change', e => { const f = e.target.files[0]; if(f) dzLeerPlantilla(f); });
  inp.click();
}
async function dzLeerPlantilla(file){
  if(typeof ExcelJS === 'undefined'){ alert('No se pudo cargar la librería de Excel (sin conexión).'); return; }
  const buf = await file.arrayBuffer();
  const wb = new ExcelJS.Workbook();
  try{ await wb.xlsx.load(buf); }catch(err){ alert('No se pudo leer el Excel: ' + err.message); return; }
  const d = disenoDe();
  const leerHoja = (nombre, cols) => {
    const ws = wb.worksheets.find(w => w.name.toLowerCase() === nombre.toLowerCase()); if(!ws) return null;
    const head = ws.getRow(1).values || [], colFor = {};
    for(let i = 1; i < head.length; i++){
      const h = celTexto(head[i]).trim().toLowerCase();
      const col = cols.find(cc => cc.t.toLowerCase() === h); if(col) colFor[i] = col.k;
    }
    const out = [];
    for(let r = 2; r <= ws.rowCount; r++){
      const row = ws.getRow(r), o = {}; let algo = false;
      Object.keys(colFor).forEach(i => { const v = celTexto(row.getCell(+i).value).trim(); if(v){ o[colFor[i]] = v; algo = true; } });
      if(algo) out.push(o);
    }
    return out;
  };
  const msg = [];
  /** @type {[string, string, any][]} */([['Vias', 'vias', DZCOLS.vias], ['Agujas', 'agujas', DZCOLS.agujas], ['Piquetes', 'piquetes', DZCOLS.piquetes], ['Estaciones', 'estaciones', DZCOLS.estaciones]])
    .forEach(([nom, key, cols]) => { const r = leerHoja(nom, cols); if(r){ d[key] = r; msg.push(r.length + ' ' + key); } });
  const wp = wb.worksheets.find(w => w.name.toLowerCase() === 'parametros');
  if(wp){
    const hd = wp.getRow(1).values || [], col = {};
    for(let i = 1; i < hd.length; i++) col[celTexto(hd[i]).trim().toLowerCase()] = i;
    const cel = etq => { const i = col[etq]; return i ? celTexto(wp.getRow(2).getCell(i).value).trim() : ''; };
    d.parametros.linea = cel('tipo de línea') || d.parametros.linea;
    if(/^RAM$/i.test(d.parametros.linea)) d.parametros.linea = 'Ancho Métrico';
    d.parametros.catAM = cel('categoría ram') || d.parametros.catAM;
    d.parametros.bloqueo = cel('bloqueo') || d.parametros.bloqueo;
    d.parametros.sistemas = cel('sistemas') || d.parametros.sistemas;
    d.parametros.gradiente = cel('gradiente medio (‰)') || d.parametros.gradiente;
  }
  const wf = wb.worksheets.find(w => w.name.toLowerCase() === 'distfrenado');
  if(wf){
    const df = [];
    for(let r = 2; r <= wf.rowCount; r++){
      const v = celTexto(wf.getRow(r).getCell(1).value).trim(), dd = celTexto(wf.getRow(r).getCell(2).value).trim();
      if(v || dd) df.push({vel:v, dist:dd});
    }
    /* solo se guarda como override si difiere de la curva NAG para estos parámetros */
    const gN = parseFloat(String(d.parametros.gradiente || '').replace(',', '.')) || 0;
    const nagC = nagCurvaFrenado(d.parametros.linea, d.parametros.catAM, gN);
    const igualNAG = df.length === nagC.length && df.every((r, i) => String(r.vel) === nagC[i].vel && String(r.dist) === nagC[i].dist);
    if(df.some(r => r.dist) && !igualNAG) d.parametros.distFrenado = df; else d.parametros.distFrenado = [];
  }
  save(); currentView = 'entrada'; render();
  alert('Plantilla importada: ' + (msg.join(', ') || 'sin filas') + '.');
}
