/* --- motor de generación NAS 811 (Fase 2) --- */
function dzGenerar(){
  const d = disenoDe(), P = d.parametros || {};
  if((d.generados || []).some(g => g.editado) && !confirm('Hay elementos generados que has editado o movido a mano en el esquema. Regenerar los descartará. ¿Continuar?')) return;
  const esAV = /alta velocidad/i.test(P.linea || '');
  const grad = parseFloat(String(P.gradiente || '').replace(',', '.')) || 0;   /* signo: negativo = pendiente */
  const gAbs = Math.abs(grad);
  const desliz = esAV ? (gAbs <= 10 ? 300 : gAbs <= 20 ? 350 : 420) : 250;
  const retro = esAV ? 30 : 20, cvPunta = esAV ? 30 : 20;
  const sis = P.sistemas || 'ASFA';
  const dfr = (P.distFrenado || []).map(r => ({v:parseFloat(String(r.vel).replace(',', '.')), m:parseFloat(String(r.dist).replace(',', '.'))}))
    .filter(r => isFinite(r.v) && isFinite(r.m)).sort((a, b) => a.v - b.v);
  /* distancia de frenado: override manual si el usuario rellenó la tabla; si no, NAG 0-8-5.0; si no, null */
  const frenado = v => {
    if(dfr.length){ const h = dfr.find(r => r.v >= v); return {m:(h ? h.m : dfr[dfr.length - 1].m), src:'tabla manual'}; }
    const n = nagDistParada(P.linea, P.catAM, grad, v);
    return n != null ? {m:n, src:'NAG 0-8-5.0'} : null;
  };
  let usoFrenadoNAG = false, usoFrenadoProv = false;
  const tieneASFA = /ASFA/i.test(sis), balPieM = tieneASFA ? 9 : 5;   /* NAS 840 §2.2.1.1.3 */
  const notas = [];
  /* Las vías GENERALES / BANALIZADAS son de línea (no de estación): se les fuerza est vacío.
     Las agujas de una estación pueden referirse a la vía general aunque ésta no "pertenezca" a la estación. */
  const vias = (d.vias || []).map(v => {
    const tipo = (v.tipo || 'general'), general = /general|banaliz/i.test(tipo);
    let est = String(v.est || '').trim();
    if(general && est){ notas.push('Vía ' + v.num + ': marcada como ' + tipo + ' y asignada a «' + est + '»; las vías generales son de línea, no de estación — se ignora la estación.'); est = ''; }
    let a = pkNum(v.pkIni), b = pkNum(v.pkFin);
    if(isFinite(a) && isFinite(b) && b < a){ notas.push('Vía ' + v.num + (est ? ' (' + est + ')' : '') + ': PK fin < PK inicio — se intercambian.'); const t = a; a = b; b = t; }
    return {num:String(v.num || '').trim(), est, general, a, b, tipo,
      vmax:parseFloat(String(v.vmax || '').replace(',', '.')) || (esAV ? 300 : 160)};
  });
  vias.forEach(v => v.vk = v.est + '|' + v.num);
  /* vía general de LÍNEA (la de número más bajo marcada general/banalizada, sin estación) */
  const viaGenNum = (vias.find(v => v.general) || vias.find(v => v.num === '1') || vias[0] || {num:'1'}).num;
  const viaGenDe = () => viaGenNum;
  /* resuelve un nº de vía dentro de una estación: primero la vía de esa estación, luego la general de línea, luego cualquiera con ese nº */
  const vFind = (est, num) => {
    num = String(num || '').trim();
    return vias.find(v => v.est === (est || '') && v.num === num)
        || vias.find(v => v.general && v.num === num) || null;   /* vía de la estación, o la general de línea */
  };
  /* avisos de geometría dudosa */
  const estR0 = (d.estaciones || []).map(e => ({nom:String(e.nombre || '').trim(), a:pkNum(e.pkIni), b:pkNum(e.pkFin)})).filter(e => isFinite(e.a) && isFinite(e.b));
  vias.forEach(v => {
    if(v.general || !isFinite(v.a) || !isFinite(v.b)) return;
    if(Math.abs(v.b - v.a) > 3) notas.push('Vía ' + v.num + (v.est ? ' (' + v.est + ')' : '') + ': ' + (Math.abs(v.b - v.a)).toFixed(1) + ' km de longitud — probable error de PK.');
    const er = estR0.find(r => r.nom === v.est);
    if(er && (Math.max(v.a, v.b) < Math.min(er.a, er.b) - 0.5 || Math.min(v.a, v.b) > Math.max(er.a, er.b) + 0.5))
      notas.push('Vía ' + v.num + ' (' + v.est + '): sus PK (' + toPkStr(v.a) + '–' + toPkStr(v.b) + ') caen fuera del rango de la estación (' + toPkStr(er.a) + '–' + toPkStr(er.b) + ').');
  });
  const agujas = (d.agujas || []).map(a => ({
    nom:String(a.nombre || '').trim() || '?', est:String(a.est || '').trim(), jca:pkNum(a.pkJCA), piq:pkNum(a.pkPiq),
    vo:String(a.viaOrig || '').trim(), vd:String(a.viaDest || '').trim(),
    vDir:parseFloat(String(a.vDir || '').replace(',', '.')) || 0, vDesv:parseFloat(String(a.vDesv || '').replace(',', '.')) || 0,
    entraPor:String(a.entraPor || '').trim(), punta:/punta/i.test(a.entraPor || ''),
    crec:/decreciente/i.test(a.entraPor || '') ? false : (/creciente/i.test(a.entraPor || '') ? true : null),   /* «decreciente» contiene «creciente»: comprobar primero */
    esc:String(a.escapeCon || '').trim()
  })).filter(a => isFinite(a.jca));
  agujas.forEach(a => {
    if(!a.vo) a.vo = viaGenNum;
    if(a.vo && !vFind(a.est, a.vo)) notas.push('Aguja ' + a.nom + (a.est ? ' (' + a.est + ')' : '') + ': la «vía origen» ' + a.vo + ' no existe en esa estación ni como vía general.');
    if(a.vd && !vFind(a.est, a.vd)) notas.push('Aguja ' + a.nom + (a.est ? ' (' + a.est + ')' : '') + ': la «vía destino» ' + a.vd + ' no existe en «' + (a.est || 'trayecto') + '» — no se puede trazar la unión.');
    const er = estR0.find(r => r.nom === a.est);
    if(er && (a.jca < Math.min(er.a, er.b) - 0.5 || a.jca > Math.max(er.a, er.b) + 0.5))
      notas.push('Aguja ' + a.nom + ' (' + a.est + '): su PK (' + toPkStr(a.jca) + ') cae fuera de la estación (' + toPkStr(er.a) + '–' + toPkStr(er.b) + ').');
  });
  if(!agujas.length){ alert('Añade al menos una aguja con su PK (JCA).'); return; }
  /* sentido de circulación: si «Se entra por» está vacío se deduce por la posición del PK */
  const mnP = Math.min(...agujas.map(a => a.jca)), mxP = Math.max(...agujas.map(a => a.jca)), midP = (mnP + mxP) / 2;
  agujas.forEach(a => { if(a.crec == null) a.crec = a.jca <= midP; });
  const sinEntraPor = agujas.every(a => !a.entraPor);
  const sinPiquetes = agujas.every(a => !isFinite(a.piq));
  const sinDesviada = agujas.every(a => !a.vDesv);
  if(sinEntraPor) notas.push('«Se entra por» vacío en todas las agujas: no se generan retrocesos y el sentido de las entradas se ha deducido por el orden de PK.');
  if(sinPiquetes) notas.push('Sin PK de piquete de vía libre: las salidas y los CV usan una estimación (±18 m de la aguja).');
  if(sinDesviada) notas.push('Sin velocidad desviada: no se generan indicadoras de posición de aguja.');
  const gen = [];
  const nRest = {};   /* contador de retrocesos por estación (R1, R2, … dentro de cada estación) */
  const add = (codigo, tipo, ex) => {
    const g = {id:uid(), codigo, tipo, pk:'', pkIni:'', pkFin:'', via:'', est:'', lado:'Lado derecho (abajo)', senal:'', criterio:'', revisar:false};
    if(ex.pkNum != null){ g.pk = toPkStr(ex.pkNum); delete ex.pkNum; }
    if(ex.iniNum != null){ g.pkIni = toPkStr(ex.iniNum); delete ex.iniNum; }
    if(ex.finNum != null){ g.pkFin = toPkStr(ex.finNum); delete ex.finNum; }
    gen.push(Object.assign(g, ex));
  };
  agujas.forEach(a => {
    const sg = a.crec ? 1 : -1;
    const piq = isFinite(a.piq) ? a.piq : a.jca + sg * 0.018;   /* piquete de vía libre: lado del haz de la aguja */
    if(a.punta) add('R' + (nRest[a.est] = (nRest[a.est] || 0) + 1), 'Señal de retroceso', {via:a.vo, est:a.est, pkNum:a.jca - sg * retro / 1000, _dir:sg,
      criterio:'NAS 811 §6.2: retroceso a ' + retro + ' m de la punta de Ag.' + a.nom + ', antes de la bifurcación (lado de aproximación por la punta)' + (a.est ? ' — ' + a.est : '')});
    if(a.vDesv && (!a.vDir || a.vDesv < a.vDir)) add('IA' + a.nom, 'Indicadora de posición de aguja',
      {via:a.vo, est:a.est, pkNum:a.jca - sg * 5 / 1000, criterio:'NAS 811 §6.2: indicadora a 5 m antes de la Ag.' + a.nom + ' (en el sentido de entrada por la punta)'});
    const f1 = a.jca - sg * cvPunta / 1000, f2 = piq + sg * 5 / 1000;
    add('CV A' + a.nom, 'Circuito de vía', {via:a.vo, est:a.est, iniNum:Math.min(f1, f2), finNum:Math.max(f1, f2),
      criterio:'NAS 811 §6.3: frontera a ' + cvPunta + ' m de la punta y 5 m antes del piquete de Ag.' + a.nom,
      revisar:Math.abs(f2 - f1) * 1000 < 20});
    if(a.esc) add('PN ' + a.nom + '-' + a.esc, 'Punto negro', {via:a.vo, est:a.est, pkNum:a.jca,
      criterio:'NAS 811 §6.6: escape ' + a.nom + '-' + a.esc + ' → falta de gálibo por defecto (confirmar en replanteo)'});
  });
  /* agrupar agujas por ESTACIÓN (columna «Estación»); vacía = grupo "(trayecto)" */
  const grupos = {};
  agujas.forEach(a => { const k = a.est || '(trayecto)'; (grupos[k] = grupos[k] || []).push(a); });
  /* señales de salida: cada vía de la estación tiene una salida en cada cabecera que alcanza.
     lado 1 = cabecera de menor PK, lado 2 = la de mayor PK. Código S<lado>/<vía>. */
  Object.keys(grupos).forEach(k => {
    const ags = grupos[k], est = k === '(trayecto)' ? '' : k, jcas = ags.map(a => a.jca);
    /* punto medio entre las agujas de la estación: separa la cabecera lado 1 (PK bajo) de la lado 2 (PK alto) */
    const mid = (Math.min(...jcas) + Math.max(...jcas)) / 2;
    let lados = [{lado:1, ags:ags.filter(a => a.jca < mid)}, {lado:2, ags:ags.filter(a => a.jca >= mid)}].filter(L => L.ags.length);
    if(lados.length === 1) lados[0].lado = 1;
    /* vías de la estación + la(s) vía(s) general(es) de línea que pasan por esa cabecera */
    vias.filter(v => (v.est === est || v.general) && isFinite(v.a) && isFinite(v.b)).forEach(v => {
      const lo = Math.min(v.a, v.b), hi = Math.max(v.a, v.b);
      lados.forEach(L => {
        const zj = L.ags.map(a => a.jca), zmin = Math.min(...zj), zmax = Math.max(...zj);
        const conecta = L.ags.some(a => a.vo === v.num || a.vd === v.num);
        const atraviesa = lo <= zmin + 0.03 && hi >= zmax - 0.03;
        if(!conecta && !atraviesa) return;
        const extremo = L.lado === 1 ? lo : hi;
        const cand = L.ags.filter(a => a.vo === v.num || a.vd === v.num);
        const aRef = (cand.length ? cand : L.ags).slice().sort((x, y) => Math.abs(x.jca - extremo) - Math.abs(y.jca - extremo))[0];
        /* la salida se coloca ENTRE la aguja y la estación (zona de ≥2 vías), nunca en la vía general suelta.
           lado 1 = aguja de PK bajo → la estación está a PK mayor; lado 2 al revés. */
        const piqRef = isFinite(aRef.piq) ? aRef.piq : aRef.jca + (L.lado === 1 ? 0.018 : -0.018);
        const esApartado = !v.general;
        const vConf = aRef.vDir || v.vmax || 0;
        const ri = (esApartado && vConf > 30) ? nagRebaseIndebido(P.linea, grad) : null;
        const offS = ri != null ? ri : 5;
        let pkS = L.lado === 1 ? piqRef + offS / 1000 : piqRef - offS / 1000;
        pkS = L.lado === 1 ? Math.max(pkS, aRef.jca + 0.002) : Math.min(pkS, aRef.jca - 0.002);
        const dnd = est ? ' (' + est + ', cabecera lado ' + L.lado + ')' : ' (cabecera lado ' + L.lado + ')';
        add('S' + L.lado + '/' + v.num, 'Señal de salida', {via:v.num, est:est, pkNum:pkS, _dir:(L.lado === 1 ? -1 : 1),
          criterio:ri != null
            ? ('NAS 811 §6.11 + NAG 0-8-5.0 §5: salida de la vía ' + v.num + dnd + ' a ' + ri + ' m del piquete de Ag.' + aRef.nom + ' — protección de rebase indebido (V confluencia ' + vConf + ' > 30 km/h)')
            : ('NAS 811 §6.2: salida de la vía ' + v.num + dnd + ' a ≥5 m del piquete de Ag.' + aRef.nom)});
      });
    });
  });
  const emitir = (a, dir) => {
    /* numeración de entradas INVERSA a la posición (petición del usuario, v37):
       E1 + E'1 protegen la cabecera de MAYOR PK, E2 + E'2 la de MENOR PK.
       La colocación (pkE / avanzada) sigue la geometría por `dir`; solo cambia el número. */
    const lado = dir === 1 ? 2 : 1;
    const vmax = (vFind(a.est, a.vo) || {}).vmax || (esAV ? 300 : 160);
    const pkE = a.jca - dir * (desliz + retro) / 1000;
    const donde = a.est ? ' de ' + a.est : '';
    add('E' + lado, 'Señal de entrada', {via:a.vo, est:a.est, pkNum:pkE, _dir:dir, lado:dir === 1 ? 'Lado derecho (abajo)' : 'Lado izquierdo (arriba)',
      criterio:'NAS 811 §6.2 + §6.10: entrada' + donde + ' (lado ' + lado + ') a distancia de deslizamiento (' + desliz + ' m) de la zona de agujas (Ag.' + a.nom + ')' + (sinEntraPor ? ' — sentido asumido por PK' : ''),
      revisar:sinEntraPor});
    const fr = frenado(vmax);
    if(fr && fr.src === 'NAG 0-8-5.0') usoFrenadoNAG = true;
    if(!fr) usoFrenadoProv = true;
    add("E'" + lado, 'Señal avanzada', {via:a.vo, est:a.est, pkNum:pkE - dir * ((fr ? fr.m : 1000)) / 1000, _dir:dir, lado:dir === 1 ? 'Lado derecho (abajo)' : 'Lado izquierdo (arriba)',
      criterio:fr ? ('NAS 811 §6.2: avanzada a distancia de frenado (' + fr.m + ' m) para ' + vmax + ' km/h en declividad ' + (grad || 0) + '‰ — ' + fr.src)
                  : 'NAS 811 §6.2: avanzada a distancia de frenado — sin dato NAG ni tabla manual; valor provisional 1000 m',
      revisar:!fr || sinEntraPor});
  };
  Object.keys(grupos).forEach(k => {
    const ord = grupos[k].slice().sort((x, y) => x.jca - y.jca);
    emitir(ord[0], 1);
    if(ord.length > 1) emitir(ord[ord.length - 1], -1);
  });
  vias.forEach(v => {
    if(v.general || !isFinite(v.a) || !isFinite(v.b)) return;
    add('CV ' + v.num, 'Circuito de vía', {via:v.num, est:v.est, iniNum:Math.min(v.a, v.b), finNum:Math.max(v.a, v.b),
      criterio:'NAS 811 §6.3: circuito de vía de estacionamiento de la vía ' + v.num + (v.est ? ' (' + v.est + ')' : ''), revisar:Math.abs(v.b - v.a) * 1000 < 20 || Math.abs(v.b - v.a) > 3});
  });
  /* toperas: marca de fin de vía (NAS 840 §2.4.2.2 / §2.4.4.8, NAS 811 §6.8c) */
  vias.forEach(v => {
    if(!/topera/i.test(v.tipo) || !isFinite(v.a) || !isFinite(v.b)) return;
    const ags = agujas.filter(a => a.est === v.est && (a.vo === v.num || a.vd === v.num));
    const cen = (v.a + v.b) / 2;
    const refJca = ags.length ? ags.slice().sort((x, y) => Math.abs(x.jca - cen) - Math.abs(y.jca - cen))[0].jca : cen;
    const topPk = Math.abs(v.a - refJca) > Math.abs(v.b - refJca) ? v.a : v.b;
    add('TOP ' + v.num, 'Topera', {via:v.num, est:v.est, pkNum:topPk,
      criterio:'NAS 840 §2.4.2.2/§2.4.4.8 + NAS 811 §6.8c: fin de vía; EoA 10 m antes de la topera, velocidad de liberación 10 km/h, longitud útil hasta 5 m de visibilidad de la topera.'});
  });
  gen.filter(g => /^Señal/.test(g.tipo)).slice().forEach(g => {
    const pkN = pkNum(g.pk); if(!isFinite(pkN)) return;
    const dd = g._dir || 1;
    add('BGS ' + g.codigo, 'Baliza', {via:g.via, est:g.est, pkNum:pkN - dd * balPieM / 1000, senal:g.codigo,
      criterio:'NAS 840 §2.2.1.1.3: última baliza del grupo de pie de ' + g.codigo + ' a ' + balPieM + ' m (' + (tieneASFA ? 'con ASFA' : 'sin ASFA') + ')'});
    if(/retroceso/i.test(g.tipo)) return;   /* sin balizas infill para retroceso — NAS 840 §2.2.1.2 */
    const inf = (esAV && /entrada/i.test(g.tipo)) ? 500 : 300;
    /* el grupo infill no puede salirse de la vía (p. ej. toperas cortas): se acota al tramo de la vía */
    let infPk = pkN - dd * inf / 1000, infReal = inf, movida = false;
    const vObj = vFind(g.est, g.via);
    if(vObj && isFinite(vObj.a) && isFinite(vObj.b)){
      const lo = Math.min(vObj.a, vObj.b) + 0.005, hi = Math.max(vObj.a, vObj.b) - 0.005;
      if(infPk < lo){ infPk = lo; movida = true; }
      if(infPk > hi){ infPk = hi; movida = true; }
      infReal = Math.round(Math.abs(infPk - pkN) * 1000);
    }
    if(infReal < 50){
      notas.push('Señal ' + g.codigo + ' (vía ' + g.via + (g.est ? ', ' + g.est : '') + '): sin longitud para su grupo de balizas infill (mín. 50 m, NAS 840 §2.2.1.12); se omite — requiere análisis.');
    } else {
      add('BGI ' + g.codigo, 'Baliza infill', {via:g.via, est:g.est, pkNum:infPk, senal:g.codigo,
        criterio:'NAS 840 §2.2.1.9/10: grupo de balizas infill a ' + infReal + ' m de ' + g.codigo + (movida ? ' — reubicado dentro de la vía (menos de ' + inf + ' m por falta de longitud, NAS 840 §2.2.1.12)' : '') + ' (mín. 50 m señal–infill)',
        revisar:movida});
    }
  });
  gen.forEach(g => { delete g._dir; });
  if(usoFrenadoNAG) notas.push('Distancia de frenado de las avanzadas: tomada de la NAG 0-8-5.0 (ED1+M1+M2) para «' + (P.linea || 'Convencional') + '»' + (nagEsRAM(P.linea) ? ' cat. ' + (P.catAM || '0') : '') + ' y declividad ' + (grad || 0) + '‰.');
  if(usoFrenadoProv) notas.push('Alguna avanzada usa un valor provisional de 1000 m (sin dato NAG ni tabla manual para esa red/velocidad).');
  const nrev = gen.filter(g => g.revisar).length;
  d.generados = gen;
  d.notasGen = notas;
  registrarCambio('alta (diseño)', 'generados ' + gen.length + ' elementos NAS 811');
  save(); currentView = 'bd'; render();
  alert('Generados ' + gen.length + ' elementos (' + gen.filter(g => /entrada/.test(g.tipo)).length + ' entradas, ' +
    gen.filter(g => /avanzada/.test(g.tipo)).length + ' avanzadas, ' + gen.filter(g => /salida/.test(g.tipo)).length + ' salidas)' +
    (nrev ? '. ' + nrev + ' marcados «revisar»' : '') + (notas.length ? '.\n\nAvisos:\n· ' + notas.join('\n· ') : '.'));
}
async function dzExportGenerados(){
  const d = disenoDe();
  if(typeof ExcelJS === 'undefined'){ alert('No se pudo cargar la librería de Excel (sin conexión).'); return; }
  if(!(d.generados || []).length){ alert('No hay elementos generados.'); return; }
  const wb = new ExcelJS.Workbook(); wb.creator = 'Vía · Diseño';
  const ws = wb.addWorksheet('Señalización generada');
  ws.columns = [
    {header:'Código', key:'codigo', width:16}, {header:'Tipo', key:'tipo', width:26}, {header:'Estación', key:'est', width:16},
    {header:'PK', key:'pk', width:12}, {header:'PK inicio', key:'pkIni', width:12}, {header:'PK fin', key:'pkFin', width:12},
    {header:'Vía', key:'via', width:8}, {header:'Lado', key:'lado', width:20},
    {header:'Señal asociada', key:'senal', width:14}, {header:'Criterio (NAS 811)', key:'criterio', width:70},
    {header:'Revisar', key:'revisar', width:10}
  ];
  ws.getRow(1).font = {bold:true};
  d.generados.forEach(g => ws.addRow(Object.assign({}, g, {revisar:g.revisar ? 'SÍ' : ''})));
  const buf = await wb.xlsx.writeBuffer();
  descargar('senalizacion_' + ((proyActivo().nombre || 'proyecto').replace(/[^\w\-]+/g, '_')) + '.xlsx', buf, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
}
function dzEnviarASeguimiento(){
  const d = disenoDe();
  if(!(d.generados || []).length){ alert('No hay elementos generados.'); return; }
  const segs = proyectosDelModo('seguimiento');
  const sel = el('select', null,
    ...segs.map(p => el('option', {value:p.id}, p.nombre)),
    el('option', {value:'__nuevo'}, '➕ Nuevo proyecto de seguimiento'));
  const inN = el('input', {placeholder:'Nombre del nuevo proyecto', style:'margin-top:8px;display:' + (segs.length ? 'none' : 'block')});
  if(!segs.length) sel.value = '__nuevo';
  sel.addEventListener('change', () => { inN.style.display = sel.value === '__nuevo' ? 'block' : 'none'; });
  openModal('Enviar a seguimiento',
    el('div', {class:'field'}, el('span', {class:'flab'}, 'Proyecto de seguimiento destino'), sel, inN),
    () => {
      let pid = sel.value;
      if(pid === '__nuevo'){
        const nm = inN.value.trim() || ('Obra ' + (proyActivo().nombre || ''));
        pid = uid();
        state.proyectos.push({id:pid, nombre:nm, creado:Date.now(), pdf:'', historial:[], modo:'seguimiento'});
      }
      const mapa = {
        'Señal de entrada':['t_senal', 'Entrada'], 'Señal de salida':['t_senal', 'Salida'],
        'Señal avanzada':['t_senal', 'Avanzada'], 'Señal de retroceso':['t_senal', 'Retroceso'],
        'Indicadora de posición de aguja':['t_senal', ''], 'Circuito de vía':['t_cdv', null],
        'Baliza':['t_bal', null], 'Baliza infill':['t_bal', null], 'Punto negro':['t_hito', null], 'Topera':['t_hito', null]
      };
      let n = 0;
      d.generados.forEach(g => {
        const m = mapa[g.tipo]; if(!m) return;
        const val = {};
        if(g.pk) val.f_pk = g.pk;
        if(g.pkIni) val.f_pkini = g.pkIni;
        if(g.pkFin) val.f_pkfin = g.pkFin;
        if(g.via) val.f_via = g.via;
        if(m[1]) val.f_tsenal = m[1];
        if(g.senal) val.f_senasoc = g.senal;
        if(g.lado) val.f_lado = g.lado;
        val.f_obs = (g.criterio || '') + (g.revisar ? ' [REVISAR]' : '');
        state.elementos.push({id:uid(), proyectoId:pid, tipoId:m[0], codigo:g.codigo, valores:val, hist:[], plano:null, creado:Date.now(), modificado:Date.now()});
        n++;
      });
      state.modo = 'seguimiento'; state.proyectoActivo = pid; currentView = 'bd';
      registrarCambio('alta (diseño)', n + ' elementos importados desde Diseño de obra');
      save(); render();
      alert(n + ' elementos enviados a "' + (state.proyectos.find(p => p.id === pid) || {}).nombre + '".');
    });
}
function viewGenerar(){
  const d = disenoDe();
  const c = el('div', null);
  c.appendChild(el('div', {class:'sec-title'}, 'Generar señalización', el('span', {class:'muted'}, 'NAS 811')));
  const n = k => (d[k] || []).length;
  c.appendChild(el('div', {class:'stats'},
    ...[['vias', 'Vías'], ['agujas', 'Agujas'], ['piquetes', 'Piquetes'], ['estaciones', 'Estaciones'], ['generados', 'Generados']].map(([k, l]) =>
      el('div', {class:'stat'}, el('div', {class:'n'}, String(n(k))), el('div', {class:'l'}, l)))));
  const falta = [];
  if(!n('vias')) falta.push('vías');
  if(!n('agujas')) falta.push('agujas');
  const P = d.parametros || {};
  const hayManual = (P.distFrenado || []).some(r => r.dist);
  const gradN = parseFloat(String(P.gradiente || '').replace(',', '.')) || 0;
  const frSrc = hayManual ? 'tabla manual (override)'
    : (nagDistParada(P.linea, P.catAM, gradN, 160) != null
        ? 'NAG 0-8-5.0 automática · ' + (P.linea || 'Convencional') + (nagEsRAM(P.linea) ? ' cat. ' + (P.catAM || '0') : '') + ' · ' + gradN + '‰'
        : null);
  const card = el('div', {class:'card', style:'margin-top:16px'});
  card.appendChild(el('div', {class:'card-b'},
    el('p', null, 'Genera retrocesos, salidas, indicadoras de posición de aguja, señales de entrada/avanzada, circuitos de vía, balizas de pie (BGS) e infill (BGI) y puntos negros a partir de las agujas, los piquetes y los parámetros. Cada elemento lleva su PK calculado y el criterio NAS 811 / NAS 840 / NAG 0-8-5.0 aplicado.'),
    falta.length ? el('p', {style:'color:var(--amb)'}, 'Faltan datos: ' + falta.join(', ') + '.') : null,
    el('p', {style:'color:var(--tx2);font-size:12px'}, 'Distancia de frenado: ' + (frSrc || 'sin dato para esta red → valor provisional 1000 m (revisar)') + '. Rebase indebido (§6.11): ' + (nagEsRAM(P.linea) ? 'tabla RAM' : 'tabla CONV/AV') + ' de la NAG 0-8-5.0 §5.'),
    el('button', {class:'btn red', ...(falta.length ? {disabled:'disabled'} : {}), onclick:dzGenerar}, 'Generar señalización')));
  c.appendChild(card);
  return c;
}
function viewBDDiseno(){
  const d = disenoDe();
  const c = el('div', null);
  c.appendChild(el('div', {class:'sec-title'}, 'Base de datos · Diseño',
    el('span', {class:'muted'}, (d.generados || []).length + ' elementos generados')));
  if(!(d.generados || []).length){
    c.appendChild(el('p', {class:'hint'}, 'Todavía no hay elementos generados. Introduce la geometría en «Datos de entrada» y usa «Generar señalización».'));
    return c;
  }
  c.appendChild(el('div', {class:'dz-actions'},
    el('button', {class:'btn red', onclick:dzExportGenerados}, '⬇ Exportar Excel'),
    el('button', {class:'btn', onclick:dzEnviarASeguimiento}, '➡ Enviar a seguimiento'),
    el('button', {class:'btn', onclick:dzGenerar}, '↻ Regenerar'),
    el('button', {class:'btn ghost danger', onclick:() => { if(confirm('¿Borrar los elementos generados?')){ d.generados = []; save(); render(); } }}, 'Vaciar generados')));
  const rev = d.generados.filter(g => g.revisar).length;
  if(rev) c.appendChild(el('p', {style:'color:var(--amb);font-size:12px'}, rev + ' elemento(s) marcados «revisar» (sin dato suficiente para fijar el PK con seguridad).'));
  (d.notasGen || []).forEach(t => c.appendChild(el('p', {style:'color:var(--tx2);font-size:12px;margin:2px 0'}, '· ' + t)));
  const wrap = el('div', {class:'tablewrap'});
  const tb = el('table', null);
  tb.appendChild(el('tr', null, ...['Código', 'Tipo', 'Estación', 'PK', 'PK ini', 'PK fin', 'Vía', 'Criterio (NAS 811)', ''].map(h => el('th', null, h))));
  d.generados.forEach((g, i) => tb.appendChild(el('tr', {style:g.revisar ? 'background:var(--ambbg)' : ''},
    el('td', null, g.codigo || ''), el('td', null, g.tipo || ''), el('td', null, g.est || ''), el('td', null, g.pk || ''),
    el('td', null, g.pkIni || ''), el('td', null, g.pkFin || ''), el('td', null, g.via || ''),
    el('td', {style:'font-size:12px;color:var(--tx2)'}, g.criterio || ''),
    el('td', null, el('button', {class:'btn sm ghost', title:'Quitar', onclick:() => { d.generados.splice(i, 1); save(); render(); }}, '✕')))));
  wrap.appendChild(tb); c.appendChild(wrap);
  return c;
}
