    (d.vias || []).forEach(v => { if(eq(v.est)){ ep.push(num(v.pkIni), num(v.pkFin)); } });
    (d.agujas || []).forEach(a => { if(eq(a.est)){ ep.push(num(a.pkJCA), num(a.pkPiq)); } });
