  const ORD = ['Señal de entrada', 'Señal avanzada', 'Señal de salida', 'Señal de retroceso', 'Indicadora de posición de aguja', 'Circuito de vía', 'Baliza', 'Baliza infill', 'Punto negro', 'Topera'];
