function verTokens(){
  extraerTokens().then(tokens => {
    const txt = tokens.map(t => t.page + '\t' + Math.round(t.x) + '\t' + Math.round(t.y) + '\t' + t.str).join('\n');
    const ta = el('textarea', {rows:16, readonly:'readonly', style:'font-family:ui-monospace,monospace;font-size:12px;white-space:pre'}, 'pagina\tx\ty\ttexto\n' + txt);
    openModal('Texto extraído (' + tokens.length + ' fragmentos)',
      el('div', null,
        el('p', {class:'hint', style:'margin-top:0'}, 'Cópialo y pásamelo para ajustar la detección a tu formato.'),
        ta,
        el('div', {style:'margin-top:10px'}, el('button', {class:'btn sm', onclick:() => { ta.select(); document.execCommand('copy'); }}, 'Copiar todo'))
      ), null);
  }).catch(err => alert('Error: ' + err.message));
}
function configPatrones(){
  const list = clone(state.patrones || []);
  const wrap = el('div', null);
  function pinta(){
    wrap.innerHTML = '';
    list.forEach((p, i) => {
      wrap.appendChild(el('div', {class:'fieldrow', style:'grid-template-columns:1fr 1fr auto'},
        el('input', {value:p.regex != null ? p.regex : ('tabla: ' + p.tabla), title:'Regex, o "tabla: NOMBRE"',
          onchange:e => { const v = e.target.value.trim();
            if(/^tabla:/i.test(v)){ p.tabla = v.replace(/^tabla:/i, '').trim(); delete p.regex; }
            else { p.regex = v; delete p.tabla; } }}),
        el('select', {onchange:e => p.tipoId = e.target.value},
          ...state.elementTypes.map(t => el('option', {value:t.id, ...(t.id === p.tipoId ? {selected:'selected'} : {})}, t.nombre))),
        el('button', {class:'btn icon sm danger', onclick:() => { list.splice(i, 1); pinta(); }}, '✕')
      ));
    });
  }
  pinta();
  openModal('Patrones de detección',
    el('div', null,
      el('p', {class:'hint', style:'margin-top:0'}, 'Regex sobre códigos del esquema, o "tabla: SEÑALES" para leer una tabla del plano.'),
      wrap,
      el('button', {class:'btn sm', style:'margin-top:10px', onclick:() => { list.push({id:uid(), regex:'', tipoId:state.elementTypes[0].id}); pinta(); }}, '+ Patrón')
    ),
    () => { state.patrones = list; save(); }
  );
}

