function vaciarProyecto(){
  if(soloLectura()) return;
  if(!confirm('Se borrarán todos los elementos de "' + proyActivo().nombre + '". ¿Continuar?')) return;
  const n = state.elementos.filter(e => e.proyectoId === state.proyectoActivo).length;
  state.elementos = state.elementos.filter(e => e.proyectoId !== state.proyectoActivo);
  registrarCambio('baja', 'proyecto vaciado (' + n + ' elementos)');
  save(); render();
}

/* ================= exportar ================= */
function exportCSV(){
  const cols = ['Código', 'Tipo', ...state.campos.map(c => c.etiqueta)];
  const escc = s => '"' + String(s == null ? '' : s).replace(/"/g, '""') + '"';
  const lines = [cols.map(escc).join(',')];
  elementosProy().forEach(e => {
    const t = getTipo(e.tipoId) || {};
    const row = [e.codigo || '', t.nombre || ''];
    state.campos.forEach(c => row.push(e.valores[c.id] || ''));
    lines.push(row.map(escc).join(','));
  });
  descargar((proyActivo().nombre || 'elementos').replace(/[^\w\-]+/g, '_') + '.csv', '﻿' + lines.join('\r\n'), 'text/csv');
}
/* nombre de hoja Excel válido: máx 31 car., sin \/*?:[] */
function nombreHoja(s){ return String(s || 'Hoja').replace(/[\\/*?:[\]]/g, ' ').trim().slice(0, 31) || 'Hoja'; }
function campoExportable(c){ return c && c.tipo !== 'photo' && c.tipo !== 'doc'; }
async function exportXLSX(){
  if(typeof ExcelJS === 'undefined'){ alert('No se pudo cargar la librería de Excel (sin conexión). Prueba "Exportar CSV".'); return; }
  const wb = new ExcelJS.Workbook();
  wb.creator = 'Vía · Seguimiento';
  const base = elementosProy();
  state.elementTypes.forEach(t => {
    const campos = t.campos.map(r => getCampo(r.campoId)).filter(campoExportable);
    const ws = wb.addWorksheet(nombreHoja(t.nombre));
    ws.columns = [{header:'Código', key:'codigo', width:16}, ...campos.map(c => ({header:c.etiqueta + (t.campos.find(r => r.campoId === c.id).obligatorio ? ' *' : ''), key:c.id, width:22}))];
    ws.getRow(1).font = {bold:true};
    const filas = base.filter(e => e.tipoId === t.id);
    filas.forEach(e => { const row = {codigo:e.codigo || ''}; campos.forEach(c => row[c.id] = e.valores[c.id] || ''); ws.addRow(row); });
    const RELLENO = 15;
    for(let i = 0; i < RELLENO; i++) ws.addRow({codigo:''});
    const lastRow = 1 + filas.length + RELLENO;
    campos.forEach((c, idx) => {
      if(c.tipo !== 'select' && c.tipo !== 'boolean') return;
      const opts = c.tipo === 'boolean' ? ['Sí', 'No'] : (c.opciones || []);
      if(!opts.length) return;
      const col = idx + 2; /* 1=Código */
      for(let r = 2; r <= lastRow; r++){
        ws.getCell(r, col).dataValidation = {type:'list', allowBlank:true, formulae:['"' + opts.join(',').replace(/"/g, '') + '"']};
      }
    });
  });
  const buf = await wb.xlsx.writeBuffer();
  descargar((proyActivo().nombre || 'elementos').replace(/[^\w\-]+/g, '_') + '.xlsx', buf, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
}
function celTexto(v){
  if(v == null) return '';
  if(typeof v === 'object'){ if(v.text != null) return String(v.text); if(v.result != null) return String(v.result); if(v.richText) return v.richText.map(r => r.text).join(''); return ''; }
  if(v instanceof Date) return v.toISOString().slice(0, 10);
  return String(v);
}
async function importarXLSXFile(file){
  if(typeof ExcelJS === 'undefined'){ alert('No se pudo cargar la librería de Excel (sin conexión).'); return; }
  destinoProyectoModal(file.name, async pid => {
    state.proyectoActivo = pid; save();
    const buf = await file.arrayBuffer();
    const wb = new ExcelJS.Workbook();
    try{ await wb.xlsx.load(buf); }catch(err){ alert('No se pudo leer el Excel: ' + err.message); return; }
    let creados = 0, actualizados = 0, camposRellenados = 0;
    state.elementTypes.forEach(t => {
      const ws = wb.worksheets.find(w => w.name === nombreHoja(t.nombre)); if(!ws) return;
      const campos = t.campos.map(r => getCampo(r.campoId)).filter(campoExportable);
      const header = ws.getRow(1).values; /* array 1-indexed, [empty,'Código',...] */
      const colFor = {};
      for(let i = 2; i <= header.length; i++){
        const h = celTexto(header[i]).replace(/\s*\*$/, '').trim();
        const c = campos.find(cc => cc.etiqueta === h); if(c) colFor[i] = c.id;
      }
      const pid_ = state.proyectoActivo, now = Date.now();
      for(let r = 2; r <= ws.rowCount; r++){
        const row = ws.getRow(r);
        const cod = celTexto(row.getCell(1).value).trim();
        const valores = {}; let algo = false;
        Object.keys(colFor).forEach(i => { const v = celTexto(row.getCell(+i).value).trim(); if(v){ valores[colFor[i]] = v; algo = true; } });
        if(!cod && !algo) continue;
        let ex = cod ? elementosProy().find(e => e.tipoId === t.id && (e.codigo || '').trim().toLowerCase() === cod.toLowerCase()) : null;
        if(ex){
          let cambio = false;
          Object.keys(valores).forEach(cid => { if(!ex.valores[cid]){ ex.valores[cid] = valores[cid]; cambio = true; camposRellenados++; } });
          if(cambio){ ex.modificado = now; registrarCambio('edición (Excel)', (ex.codigo || t.nombre) + ': ' + Object.keys(valores).length + ' campo(s) revisados', ex.id); actualizados++; }
        } else if(algo || cod){
          const nid = uid();
          state.elementos.push({id:nid, proyectoId:pid_, tipoId:t.id, codigo:cod, valores, hist:[], plano:null, creado:now, modificado:now});
          registrarCambio('alta (Excel)', (cod || t.nombre) + ' (' + t.nombre + ')', nid);
          creados++;
        }
      }
    });
    save(); currentView = 'bd'; render();
    alert('Importación completada: ' + creados + ' elemento(s) nuevo(s), ' + actualizados + ' actualizado(s) con ' + camposRellenados + ' campo(s) rellenado(s).');
  });
}
function exportProyectoJSON(){
  descargar('via-seguimiento_' + new Date().toISOString().slice(0, 10) + '.json', JSON.stringify(state, null, 2), 'application/json');
}
document.getElementById('file-import').addEventListener('change', e => {
  const inp = /** @type {HTMLInputElement} */ (e.target);
  const f = inp.files[0]; if(!f) return;
  const r = new FileReader();
  r.onload = () => {
    try{
      const data = JSON.parse(String(r.result));
      if(!data.campos || !data.elementTypes) throw new Error('El archivo no es un proyecto de Vía · Seguimiento');
      if(!confirm('Esto reemplazará todos los datos actuales. ¿Continuar?')) return;
      state = data; migrar(); selTipoId = state.elementTypes[0] ? state.elementTypes[0].id : null;
      ultimoSnap = JSON.stringify(state); persist(ultimoSnap); render();
    }catch(err){ alert('No se pudo importar: ' + err.message); }
  };
  r.readAsText(f); inp.value = '';
});
function descargar(nombre, contenido, mime){
  const blob = new Blob([contenido], {type:mime});
  const a = el('a', {href:URL.createObjectURL(blob), download:nombre});
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
}

/* ================= modal genérico ================= */
let modalEl = null;
function openModal(titulo, bodyNode, onSave, onDelete){
  closeModal();
  const btnDel = onDelete ? el('button', {class:'btn danger', onclick:() => { if(onDelete() !== false) closeModal(); }}, 'Borrar') : null;
  modalEl = el('div', {class:'overlay', onclick:e => { if(e.target === modalEl) closeModal(); }},
    el('div', {class:'modal'},
      el('div', {class:'modal-h'}, el('h2', null, titulo), el('button', {class:'btn icon ghost', onclick:closeModal}, '✕')),
      el('div', {class:'modal-b'}, bodyNode),
      el('div', {class:'modal-f'},
        btnDel || el('span', null), el('span', {class:'spacer'}),
        el('button', {class:'btn', onclick:closeModal}, 'Cancelar'),
        el('button', {class:'btn red', onclick:() => { if(!onSave || onSave() !== false) closeModal(); }}, 'Guardar')
      )
    )
  );
  document.body.appendChild(modalEl);
}
function closeModal(){ if(modalEl){ modalEl.remove(); modalEl = null; } }
document.addEventListener('keydown', e => { if(e.key === 'Escape'){ if(document.getElementById('lightbox')) return; closeModal(); } });

